"""Single Stage 13 report; renders completed evidence without fitting."""
import json
from pathlib import Path
from report_stage12 import table,fmt
R=Path(__file__).resolve().parents[1]/'reports'
def read(n): return json.loads((R/('stage13_'+n+'.json')).read_text(encoding='utf-8'))
K=['accuracy','balanced_accuracy','macro_f1','suspicious_precision','suspicious_recall','suspicious_f1','normal_recall','roc_auc','average_precision','false_positive_rate']
HEAD=['Accuracy','Balanced accuracy','Macro F1','Precision 1','Recall 1','F1 1','Recall 0','ROC-AUC','AP','FPR']

def main():
    plan=read('plan'); reference=read('reference_reproduction'); feature=read('candidate_features'); record=read('candidate_results'); results=record['candidates']
    deps=read('growth_dependence'); imps=read('feature_concentration'); shifts=read('distribution_shift')['statistics']; decision=read('selection_decision')
    protection=read('protection'); verified=read('final_verification'); ref=results['hgb_R0']; serious={n:results[n] for n in deps}
    assert verified['result']=='PASS' and record['status']=='complete'
    s=['# MODEL V3 — STAGE 13 CONTROLLED ROBUSTNESS IMPROVEMENT\n',
       '**Technical execution: PASS. Decision: '+decision['decision']+' — '+decision['label']+'.**\n',
       decision['reason']+'\n',
       'This is the full consolidated Stage 13 report. The saved Stage 11 reference is reproduced exactly; **15 new models** were fitted under a hashed, fixed plan. Six experimental descriptors were extracted twice from frozen Train/Validation observable transactions. The official 32-feature representation, targets and earlier artifacts remain unchanged. Every comparison uses **threshold 0.50**.\n',
       '## 1. Outcome and scope\n']
    s.append(table(['Candidate','Macro F1','Recall 1','AP','FPR','N3 recall','A4 recall','Growth dependence','Top feature share'],[[n,v['validation']['macro_f1'],v['validation']['suspicious_recall'],v['validation']['average_precision'],v['validation']['false_positive_rate'],v['families']['N3']['recall'],v['families']['A4']['recall'],deps[n]['classification'],imps[n]['top_share']] for n,v in serious.items()]))
    s.append('Candidate recommendation for later selection: **'+str(decision['recommended_for_later_selection'] or 'none')+'**. '+('The Stage 11 reference remains the protected development benchmark.' if decision['stage11_reference_retained'] else 'This recommendation is for a later authorized selection stage only.')+' No final production model or final threshold is declared.\n')
    s.append('The full HGB extension (`hgb_R3`) raises Macro F1 **0.9521→0.9561**, N3 recall **22/41→24/41**, and A4 recall **249/337→264/337**. H1 false positives fall **39→33** and H5 remains **21**. These gains do not solve the main robustness concern: matched growth removal has dependence index **0.3139 (EXTREME)** and the growth feature holds **63.4%** of absolute permutation importance, versus **61.5%** in the reference.\n\nThe full XGBoost extension (`xgb_R3`) detects **28/41 N3** but **241/337 A4**, with **26 H5 false positives**. Its dependence remains **EXTREME (0.2665)** and its top-feature share is **67.5%** under the same permutation method. No tested added-feature model passes all the preregistered robustness gates.\n')
    s.append('The initial instruction limited data to existing matrices/artifacts while also requesting new history descriptors. The user explicitly authorized reading frozen Train/Validation observable transactions and diagnostic metadata. The extractor receives only eight public event fields: transaction ID, UTC timestamp, sender, receiver, amount in minor units, transaction type, agent ID and serviced wallet. Targets/provenance/evidence are joined only for diagnostic slices and never enter candidate extraction, fit inputs or prediction inputs. Train labels alone supervise fitting.\n\nModel inputs use corrected Stage 10A Train **60,000 rows** and Validation **15,000 rows**, with frozen class counts **39,781/20,219** and **9,945/5,055**. Six new columns are stored separately and concatenated in memory. No history crosses partitions. No holdout directory was enumerated or evaluation file opened/hashed; named public commitment metadata alone was checked. No Validation fit, dataset regeneration, target change or application integration occurred.\n')
    s.append('## 2. Preregistered experiment and selection rules\n')
    s.append(table(['Property','Value'],[['Plan saved UTC',plan['saved_at_utc']],['Plan SHA-256',(R/'stage13_plan.sha256').read_text().strip()],['First new fit UTC',min(v['started_at_utc'] for v in results.values() if not v['reuse'])],['New fits',record['new_fit_count']],['Reused models',3],['Total evaluated representations',len(results)],['Seed',plan['seed']],['Threshold',plan['threshold']],['Wall seconds',record['wall_seconds']],['Environment',plan['environment']]]))
    s.append('The fixed design has nine representations per family. R0 HGB and R0 XGBoost reuse saved Stage 11 models; HGB R0 without growth reuses Stage 12 ablation B. All other 15 are new Train fits. No hyperparameters, weights, seeds or representations were added after results. Both model families keep their saved Stage 11 estimator configurations. HGB uses positive sample weight 1.5 versus negative 1; XGBoost uses its saved balanced positive weight ratio 39,781/20,219, with no extra sample weights. All inputs retain documented sentinels; no scaler, clipping, imputer or missingness indicators were fitted.\n')
    s.append(table(['Family','Exact estimator parameters'],[[k,v] for k,v in plan['configurations'].items()]))
    s.append('XGBoost’s nonfinite default `missing=NaN` is serialized as text `nan` in the plan for strict JSON validity; the cloned estimator retains the original default. This does not convert finite -1/-3 markers into missing values.\n')
    s.append(table(['Representation','Columns','Role'],[[k,len(v),'Matched removal diagnostic' if 'no_growth' in k or k in ('R4','R5') else 'Serious comparison'] for k,v in plan['representations'].items()]))
    s.append('R0=official 32; R1=32+three graph descriptors; R2=32+three cash descriptors; R3=all 38; R4=R3 without growth; R5=R3 without growth and novelty. Additional R0/R1/R2 without-growth representations provide matched dependence estimates for every serious model. Removal variants never redefine the official contract. Only R1/R2/R3 can qualify as an added-feature robustness recommendation.\n\n'+plan['dependence_rule']+'\n')
    s.append(table(['Recommendation gate','Requirement'],[
        ['Macro F1','At least reference minus 0.015'],['Suspicious recall / F1','At least reference minus 0.030 / 0.025'],['AP','At least reference minus 0.020'],['FPR','At most reference plus 0.010'],
        ['N3 / A4 recall','At least reference plus 0.100 / 0.030'],['H1 and H5 FPR','Each at most reference plus 0.020'],['Each domain-only recall','At least reference minus 0.030'],
        ['Growth dependence','Index <0.15 and at least 0.05 below Stage 12 index 0.3186943620'],['Top-feature absolute share','At most 0.50 and at least 0.10 below reference'],['Top-three / top-five shares','Each at most reference plus 0.05'],['Train–Validation Macro F1 gap','At most 0.04']]))
    s.append('All gates must pass. '+plan['selection_order']+' These are preregistered research tolerances, not confidence bounds or regulatory requirements. Higher ROC-AUC and all class metrics are reported for context; there is no hidden composite score.\n\nDecision precedence was also fixed: '+plan['decision_order']+'\n\n'+ '; '.join(plan['stop_conditions'])+'.\n')
    s.append('## 3. Exact experimental feature contract\n\nMaximum six new columns: three N3-related and three A4-related. These are candidate descriptors only. Each is computable using decision-time observables and partition-local state. Monetary sums remain integer minor units until final division. Prior keys are strictly smaller `(UTC timestamp, integer transaction_id)`; same-time smaller IDs are prior, larger IDs are future. State updates after emission. Recent lower boundaries are open. Baselines precede and exclude the recent window.\n')
    for i,f in enumerate(feature['definitions'],33):
        s.append(f"### {i}. `{f['name']}`\n")
        s.append(table(['Contract item','Definition'],[[k,f[k]] for k in ('domain','formula','current','prior','window','baseline','zero_missing','meaning','non_oracle')]))
    s.append('No feature returns an N3/A4 trigger, searches for a path satisfying the complete monetary conjunction, or combines the full count/breadth/current-role/imbalance/baseline predicates. The graph spread summarizes one topology-selected path, so it can still miss evidence on another path. Cash descriptors provide composition, persistence and unsigned magnitude; they omit the full recent event-count/unique-wallet conjunction. Features necessarily correlate with the synthetic target observables, which does not itself establish leakage. Projection and source review establish the intended input boundary; they do not prove the absence of every synthetic shortcut.\n')
    s.append(table(['Partition','Rows','New columns','Two extractions equal','Official values unchanged','Candidate file SHA-256'],[[p,v['rows'],v['new_columns'],v['repeat_extraction_exact'],v['official_values_unchanged'],v['candidate_file_sha256']] for p,v in feature['partitions'].items()]))
    s.append('The six-column arrays and IDs are stored under `evidence/stage13/`. Both extractions start empty histories and their arrays/ID order match exactly; this is numeric extraction repeatability, not a claim of two independently serialized byte sets. Saved candidate files are hashed and reloaded for verification. The original 32 matrix columns were verified unchanged before concatenation.\n')
    s.append('## 4. Causality and manual feature tests\n')
    s.append(table(['Synthetic case','Expected result'],[
        ['Isolated direct W2W','[reciprocal=0, two-hop=0, spread=-1, cash share=0, persistence=0, cash rate=-1]'],
        ['Reverse edge exactly 7d old plus another 1s old','Old boundary excluded; reciprocal count1; one-edge spread0'],
        ['Same-time r→m ID1, m→s ID2, then closure','Two-hop count1; amounts100→400 give spread log(4)'],
        ['Swap the two prior IDs','Chronology reverses; count0 and no selected path'],
        ['Two first-leg edges followed by two second-leg edges','Four chronological edge-pairs'],['Current self-loop','Graph counts0; spread missing'],
        ['Cash-Out at -18h,-12h,-6h,0; extra at -24h','Lower boundary excluded; cash share1 and persistence1'],
        ['Replace current with Cash-In / assisted W2W','Persistence .5 / .75; W2W cash-service share .75'],
        ['Full29d coverage,12 baseline services including8 cash of100 minor units, recent cash100','Rate100/(800/28)=3.5'],
        ['Remove first observation / reduce baseline to11 services','Missing cash rate -1'],
        ['Future records, metadata mutation and shuffled input','Earlier vectors unchanged'],['Current W2W amount perturbation','All six descriptors unchanged; no current W2W amount enters cash or prior graph spread']]))
    s.append(f"Executed **{verified['tests']['methods']} test methods**, with no failures/errors. The captured test log and source digest are in final verification. Tests use synthetic events and do not read evaluation data. Finite examples do not exhaust all possible histories.\n")
    s.append('## 5. Protected reference reproduction\n')
    s.append(table(['Partition','Exact score agreement','Max difference'],[[p,reference[p]['exact_equal'],reference[p]['max_score_difference']] for p in ('train','validation')]))
    s.append(table(['Partition']+HEAD+['Confusion [[TN,FP],[FN,TP]]'],[[p]+[ref[p][k] for k in K]+[ref[p]['confusion_matrix']] for p in ('train','validation')]))
    s.append('All domain, family and target-0 category counts/rates exactly reproduce the saved Stage 11/12 evidence. These reference slices appear as `hgb_R0` in the complete tables below. AP is Average Precision, not trapezoidal PR area. Class 1 means synthetic suspicious-pattern review target; class 0 is the negative state under the frozen definition.\n')
    s.append('## 6. All model results and generalization\n')
    for p in ('train','validation'):
        s.append('### '+p.title()+'\n')
        s.append(table(['Candidate']+HEAD+['Confusion [[TN,FP],[FN,TP]]'],[[n]+[v[p][k] for k in K]+[v[p]['confusion_matrix']] for n,v in results.items()]))
    s.append(table(['Candidate','Fit seconds','Reused artifact','Train minus Validation Macro F1','Warnings'],[[n,v['fit_seconds'],v['reuse'] or 'new Train fit',v['generalization_gap'],v['warnings']] for n,v in results.items()]))
    s.append('All results, including diagnostics and tradeoffs, are retained. Train and Validation are disjoint frozen partitions, but Validation has been reused across development stages; these gaps do not measure final unseen-population performance. No early stopping used Validation, and no representation was changed in response to these metrics.\n')
    s.append('## 7. Matched growth dependence\n\nEach comparison retrains the same estimator/weights on the same Train rows with only growth omitted. R3 compares against R4. Deltas below are removal minus full. R5 is separately reported above; it also removes novelty and is not the single-growth dependence measure.\n')
    s.append(table(['Full','Matched removal','Full Macro F1','Removed Macro F1','Index','Class'],[[n,d['removed_candidate'],results[n]['validation']['macro_f1'],results[d['removed_candidate']]['validation']['macro_f1'],d['dependence_index'],d['classification']] for n,d in deps.items()]))
    s.append(table(['Candidate','ΔMacro F1','ΔRecall1','ΔF1 1','ΔAP','ΔROC-AUC','ΔFPR','ΔAgent recall','ΔA1 recall','ΔA4 recall'],[[n]+[d['metric_deltas'][k] for k in ('macro_f1','suspicious_recall','suspicious_f1','average_precision','roc_auc','false_positive_rate')]+[d['domain_deltas']['agent'],d['family_deltas']['A1'],d['family_deltas']['A4']] for n,d in deps.items()]))
    s.append('Dependence is measured within each model family. HGB/XGBoost have different frozen weighting schemes, so cross-family differences describe their full configurations rather than an isolated algorithm effect. Permutation concentration and removal dependence are different diagnostics; distributing importance does not guarantee a small removal loss.\n')
    s.append('## 8. Domain-independent and ordinary domain recall\n\nOnly-domain slices exclude every other domain, while allowing multiple families within the named domain. `multi_domain` is the unique union of rows belonging to at least two domains; ordinary domain rows overlap and must not be added. All models, including removals, are shown.\n')
    s.append(table(['Candidate','Slice','Support','TP','FN','Recall'],[[n,k,v['support'],v['tp'],v['fn'],v['recall']] for n,row in results.items() for k,v in row['domain_independence'].items() if k.endswith('_only') or k=='multi_domain']))
    s.append(table(['Candidate','Domain','Support','TP','FN','Recall'],[[n,k,v['support'],v['tp'],v['fn'],v['recall']] for n,row in serious.items() for k,v in row['domains'].items()]))
    s.append('## 9. All twelve family slices\n\nSupport comes from frozen observable evidence labels, not private campaign membership. S2 (N=1) and S4 (N=8) are **sparse/unstable**, excluded from selection. Their individual predictions are retained for disclosure, not tuned. N3 (N=41) is also small: one changed prediction moves recall by about 2.44 percentage points. Family evidence overlaps, so counts are not additive.\n')
    s.append(table(['Candidate','Family','Support','TP','FN','Recall','Support warning'],[[n,k,v['support'],v['tp'],v['fn'],v['recall'],'sparse/unstable; not selected on' if k in ('S2','S4') else 'small support' if k=='N3' else ''] for n,row in results.items() for k,v in row['families'].items()]))
    s.append('## 10. Hard negatives and review tradeoffs\n\nFPR counts only target-0 rows. Legitimate-origin target-1 rows are not false positives under this synthetic target. Each row reports its denominator; diagnostic private category names never enter X.\n')
    s.append(table(['Candidate','Category','Support','FP','TN','FPR'],[[n,k,v['support'],v['fp'],v['tn'],v['false_positive_rate']] for n,row in results.items() for k,v in row['normal_fpr'].items()]))
    s.append(table(['Candidate','ΔN3 recall','ΔA4 recall','ΔH1 FPR','ΔH5 FPR','ΔMacro F1'],[[n,row['families']['N3']['recall']-ref['families']['N3']['recall'],row['families']['A4']['recall']-ref['families']['A4']['recall'],row['normal_fpr']['H1']['false_positive_rate']-ref['normal_fpr']['H1']['false_positive_rate'],row['normal_fpr']['H5']['false_positive_rate']-ref['normal_fpr']['H5']['false_positive_rate'],row['validation']['macro_f1']-ref['validation']['macro_f1']] for n,row in serious.items()]))
    s.append('These paired development differences disclose whether weak-family gains coincide with more legitimate-like reviews. They are not significance tests, and no threshold was adjusted to improve a slice.\n')
    s.append('## 11. Consistent feature-concentration diagnostic\n\nEvery serious R0–R3 model uses the same Validation permutation-AP procedure: three repeats, 3,000-row sample, seed20260928, one permutation worker. Scores are average AP drops; absolute values are normalized into mass shares, including negative permutation estimates. Correlated/redundant descriptors can split importance without creating independent information. Sparse families may be poorly represented in the sampled rows. This is not causal importance.\n')
    s.append(table(['Candidate','Top feature','Top share','Top3 share','Top5 share'],[[n,v['top_feature'],v['top_share'],v['top3_share'],v['top5_share']] for n,v in imps.items()]))
    domains=['current','structuring','network','agent','coverage','new_N3','new_A4']
    s.append(table(['Candidate']+domains,[[n]+[v['domain_mass'][d] for d in domains] for n,v in imps.items()]))
    old=json.loads((R/'stage11_importance.json').read_text(encoding='utf-8'))['s11_09_hist_gradient_boosting']
    s.append(table(['Reference comparison','Stage 11','Stage 13 recomputation'],[['Top feature share',old['top_feature_absolute_share'],imps['hgb_R0']['top_share']],['Agent domain mass',old['domain_absolute_mass']['agent'],imps['hgb_R0']['domain_mass']['agent']]]))
    s.append('All per-feature AP drops and repeat SDs are in `stage13_feature_concentration.json`. XGBoost is now compared using permutation AP, rather than the native normalized gain reported in Stage 11; native gain’s earlier distribution of importance is not directly comparable to these shares.\n')
    s.append('## 12. Train/Validation distribution shift\n\nObserved summaries exclude only the documented per-column marker. Missing rates use all rows in the slice. No transform or dataset change was used to reduce shift. Overall, both targets, relevant positive domains/families, routine target0 and relevant H cohorts are shown; JSON retains all twelve families, three domains and ten normal groups for all eight inspected columns.\n')
    for name in shifts['train']:
        s.append('### `'+name+'`\n')
        relevant=['N3','network','H6'] if 'prior_' in name or 'selected_path' in name else ['A4','agent','H8'] if name.startswith('candidate_agent') else ['A1','A2','agent','H7','H8']
        slices=['overall','target0','target1']+relevant+['routine']
        s.append(table(['Partition','Slice','N','Available','Missing rate','Mean','Median','SD','Q05','Q25','Q75','Q95'],[[p,label,v['support'],v['available_count'],v['missing_rate']]+[v.get(k) for k in ('mean','median','std','q05','q25','q75','q95')] for p in ('train','validation') for label in slices for v in [shifts[p][name][label]]]))
    s.append(table(['Feature','Validation−Train observed mean','Missing-rate difference'],[[n,shifts['validation'][n]['overall'].get('mean',0)-v['overall'].get('mean',0),shifts['validation'][n]['overall']['missing_rate']-v['overall']['missing_rate']] for n,v in shifts['train'].items()]))
    s.append('Growth and novelty preserve their Stage 12 shifts because the official columns are unchanged. Novelty’s observed mean remains about 0.8718 versus 0.6395 and its shift was previously found within matched slices. New graph descriptors may reflect partition-local graph density, while cash descriptors reflect service mix and baseline eligibility. The tables identify associations, not the generator mechanism; raw mean differences have different units and should not be ranked as comparable effect sizes.\n')
    s.append('The new columns also show differences worth retaining: overall two-hop return count rises **0.00485→0.01207**, while within N3 positives it falls **0.1833→0.1220**. Selected-path spread is unavailable on **98.10%/96.77%** of Train/Validation, so its observed distribution concerns a small selected subset. Overall cash-value acceleration means are nearly equal (**3.2334/3.2315**), yet A4-positive means differ substantially (**6.1151/3.4068**). Overall similarity therefore does not establish family-level stability. Persistence and cash-service share have smaller overall shifts, with A4-positive persistence **0.5859→0.5572** and cash share **0.7820→0.7746**. None of these observations was used to alter data, features or the fixed search.\n')
    s.append('## 13. Selection decision and scientific interpretation\n')
    s.append(table(['Added-feature candidate','Passed gates','Failed gates'],[[n,sum(g.values()),', '.join(k for k,v in g.items() if not v) or 'none'] for n,g in decision['gates'].items()]))
    s.append('**'+decision['decision']+' — '+decision['label']+'.** '+decision['reason']+'\n')
    s.append('The decision follows the plan’s joint gates and fixed decision precedence. A higher headline score alone cannot qualify a model for later final selection. The complete dependence, weak-family, hard-negative, domain-only and concentration results above remain part of the decision even when one metric improves.\n\n')
    s.append('HGB R3 meets the aggregate, A4, hard-negative, domain-only and gap tolerances but fails N3 improvement, dependence and top-feature concentration. XGBoost R3 meets the N3 improvement gate but fails A4, H5, dependence and top-feature concentration. R4/R5 can improve selected weak families while sacrificing the aggregate task: HGB R5 reaches A4 recall **0.9228** with Macro F1 **0.8238** and FPR **0.1004**; XGBoost R5 reaches A4 recall **0.9614** with Macro F1 **0.8024** and FPR **0.1664**. Those diagnostic results do not justify promotion.\n')
    if decision['recommended_for_later_selection']:
        s.append('Recommended only for later authorized candidate/threshold selection: `'+decision['recommended_for_later_selection']+'`. This stage does not freeze it or promote its feature contract.\n')
    else:
        s.append('No candidate is recommended for final selection by this stage. Retain the protected Stage 11 reference as the development benchmark, with its Stage 12 limitations still disclosed. Any further investigation needs a separately bounded plan; the unused fit allowance is not an invitation to expand this run.\n')
    s.append('The new descriptors target N3 and A4, while growth directly describes A1 and A1 has much greater support. Improving N3/A4 need not supply a replacement for A1 information. Large removal losses therefore establish dependence, not automatically a synthetic artifact. Conversely, a dispersed importance profile does not certify robustness. The experiment tests a small fixed set of descriptors and two configurations; failure to meet gates does not prove that all causal representations or model choices would fail.\n\nSynthetic ground truth, repeated Validation reuse, selected-path compression, sparse N3/S2/S4 support, event dependence and distribution shifts remain limitations. This stage preserves frozen targets and does not certify the reference evaluator against every original written predicate. It supports AML decision-support research, not claims of criminal intent, real-operator effectiveness or production readiness.\n')
    s.append('## 14. Protection and final verification\n')
    s.append(table(['Property','Result'],[['Protected before',len(protection['before']['files'])],['Protected after',len(protection['after']['files'])],['Changed protected paths',protection['changed']],['Public commitment unchanged',protection['public_commitment_unchanged']],['Metric sets recomputed',verified['recomputed_metric_sets']],['Artifact hashes checked',verified['artifact_hash_count']],['New model reloads checked',len(verified['new_model_reload_max_differences'])],['Maximum reload score difference',max(verified['new_model_reload_max_differences'].values())],['Final verification',verified['result']]]))
    s.append(table(['Named public metadata','Before SHA-256','After SHA-256'],[[p,h,protection['after']['public'][p]] for p,h in protection['before']['public'].items()]))
    s.append('Protection covers the explicit application/V1/V2 allowlists, frozen V3 development data/design, Stage 10A contract/matrices/code, Stage 11 candidates and Stage 12 diagnostics/reports/source. Exact paths, scopes and exclusions are saved in the protection record. No claim is made to inspect every filesystem file or freshly verify unread evaluation bytes. Public hashes certify commitment metadata only.\n\nFinal verification rechecks the plan digest/source hashes, official input hashes, all new artifact hashes, 36 Train/Validation metric sets, family/domain/normal slice counts and selected decision. All fifteen new saved models were reloaded: their Validation probabilities and threshold predictions reproduce within the recorded 1e-12 tolerance. Six causal test methods pass. No additional model fits occur during verification or reporting.\n')
    s.append('## 15. Evidence and reproducible entry points\n')
    evidence=['plan','reference_reproduction','candidate_features','candidate_results','growth_dependence','domain_independence','family_results','hard_negative_results','feature_concentration','distribution_shift','selection_decision','protection','artifact_manifest','final_verification']
    s.append(table(['Evidence','File'],[[n,f'[stage13_{n}.json](stage13_{n}.json)'] for n in evidence]))
    s.append('Source: `src/stage13_robustness_improvement.py`, `src/run_stage13.py`, `src/verify_stage13.py`, `src/report_stage13.py`; tests: `tests/test_stage13_features.py`. Commands from repository root:\n\n```powershell\npython -B -m unittest discover -s ml_v3/tests -p test_stage13_features.py -v\npython -B ml_v3/src/run_stage13.py\npython -B ml_v3/src/verify_stage13.py\npython -B ml_v3/src/report_stage13.py\n```\n\nThe runner refuses an existing Stage 13 plan/model directory. For a fresh reproduction, preserve this run and use an isolated authorized development checkout with the recorded frozen inputs, source and environment, and a newly captured Stage 13 protection-before snapshot. New feature arrays are under `evidence/stage13/`; new models/scores under `models/stage13_candidates/`. Reused models stay at their protected Stage 11/12 paths. Machine evidence distinguishes all reuse from new fits.\n\nNo holdout evaluation, final threshold optimization, calibration, Train+Validation refit, V1 replacement, Flask/dashboard integration or final feature promotion occurred.\n\n**V3 STAGE 13 COMPLETE — WAITING FOR APPROVAL.**\n')
    (R/'V3_STAGE13_ROBUSTNESS_IMPROVEMENT_REPORT.md').write_text('\n'.join(s),encoding='utf-8',newline='\n')

if __name__=='__main__': main()
